import { useState, useMemo } from 'react'
import {
  buildBoltTable, buildSlipTable,
  calcBoltStrength, calcSlipCriticalAISC, calcSlipCriticalKDS,
  BOLT_SPECS, BOLT_SIZES,
} from '../engines/boltStrength'
import ResultBox from '../components/shared/ResultBox'

const TABS = [
  { id: 'slip',    label: 'Slip Critical' },
  { id: 'tensile', label: 'Tensile' },
  { id: 'shear-n', label: 'Shear (N)' },
  { id: 'shear-x', label: 'Shear (X)' },
]

export default function BoltStrength() {
  const [tab,      setTab]      = useState('slip')
  const [selected, setSelected] = useState(null)
  const [codeStd,  setCodeStd]  = useState('AISC')  // 'AISC' | 'KDS'

  // Slip-critical options
  // AISC Class A μ=0.35, Class B μ=0.50
  // KDS  Class A μ=0.45, Class B μ=0.50
  const [slipClass,  setSlipClass]  = useState('A')
  const [slipPlanes, setSlipPlanes] = useState('1')
  const [limitState, setLimitState] = useState('serviceability')

  const mu = codeStd === 'KDS'
    ? (slipClass === 'B' ? 0.50 : 0.45)
    : (slipClass === 'B' ? 0.50 : 0.35)
  const ns = parseInt(slipPlanes)

  const isSlip = tab === 'slip'

  const table = useMemo(
    () => isSlip ? buildSlipTable(mu, ns, limitState, codeStd) : buildBoltTable(tab),
    [tab, mu, ns, limitState, codeStd]
  )

  const detail = useMemo(() => {
    if (!selected || selected.tab !== tab) return null
    if (isSlip) {
      return codeStd === 'KDS'
        ? calcSlipCriticalKDS(selected.boltKey, selected.d_mm, mu, ns, limitState)
        : calcSlipCriticalAISC(selected.boltKey, selected.d_mm, mu, ns, limitState)
    }
    return { phiRn: calcBoltStrength(selected.type, selected.boltKey, selected.d_mm) }
  }, [selected, tab, mu, ns, limitState, codeStd])

  const typeLabel = tab === 'shear-n' ? 'Shear (N) — Threads Included'
                  : tab === 'shear-x' ? 'Shear (X) — Threads Excluded'
                  : tab === 'tensile' ? 'Tensile Strength'
                  : 'Slip-Critical'

  function handleCellClick(boltKey, d_mm) {
    setSelected({ tab, type: tab, boltKey, d_mm })
  }

  const cellHighlight = (k, d) => selected?.boltKey === k && selected?.d_mm === d && selected?.tab === tab

  return (
    <div>
      <h3 style={titleStyle}>BOLT STRENGTH</h3>
      <p style={descStyle}>AISC 360-16 §J3.6 (Bearing) / §J3.8 (Slip-Critical) LRFD | KS B 1010 / ASTM F3125</p>

      {/* KDS / AISC standard toggle */}
      <div style={{ display: 'flex', gap: 8, marginBottom: 12, alignItems: 'center' }}>
        <span style={{ fontSize: 11, color: 'var(--tx-muted)', marginRight: 4 }}>Design Standard:</span>
        {['KDS', 'AISC'].map(c => (
          <button key={c} onClick={() => setCodeStd(c)} style={{
            padding: '4px 14px', borderRadius: 5, fontSize: 12, fontWeight: 700, cursor: 'pointer',
            border: `1px solid ${codeStd === c ? 'var(--ac-main)' : 'var(--bd-subtle)'}`,
            background: codeStd === c ? 'var(--ac-main)' : 'var(--bg-card)',
            color: codeStd === c ? '#000' : 'var(--tx-secondary)',
          }}>{c}</button>
        ))}
        <span style={{ fontSize: 11, color: 'var(--tx-muted)' }}>
          {codeStd === 'KDS' ? 'KDS 14 31 10 (KS B 2819)' : 'AISC 360-16'}
        </span>
      </div>

      {/* Tab bar */}
      <div style={{ display: 'flex', gap: 8, marginBottom: 20, flexWrap: 'wrap' }}>
        {TABS.map(t => (
          <button key={t.id} onClick={() => setTab(t.id)} style={{
            padding: '6px 16px', borderRadius: 6, fontSize: 12, fontWeight: 600,
            border: '1px solid var(--bd-subtle)',
            background: tab === t.id ? 'var(--ac-main)' : 'var(--bg-card)',
            color: tab === t.id ? '#000' : 'var(--tx-secondary)',
            cursor: 'pointer',
          }}>{t.label}</button>
        ))}
      </div>

      {/* Slip-critical options */}
      {isSlip && (
        <div style={{
          display: 'flex', gap: 24, flexWrap: 'wrap', marginBottom: 16,
          padding: '12px 16px', borderRadius: 8,
          background: 'var(--bg-inset)', border: '1px solid var(--bd-subtle)',
          fontSize: 13, alignItems: 'center',
        }}>
          <label style={optLabel}>
            Surface Class &nbsp;
            <select value={slipClass} onChange={e => setSlipClass(e.target.value)} style={optSel}>
              {codeStd === 'KDS' ? <>
                <option value="A">Class A — μ = 0.45 (Unpainted mill scale)</option>
                <option value="B">Class B — μ = 0.50 (Blast-cleaned)</option>
              </> : <>
                <option value="A">Class A — μ = 0.35 (Unpainted mill scale)</option>
                <option value="B">Class B — μ = 0.50 (Blast-cleaned)</option>
              </>}
            </select>
          </label>
          <label style={optLabel}>
            Shear Planes &nbsp;
            <select value={slipPlanes} onChange={e => setSlipPlanes(e.target.value)} style={optSel}>
              <option value="1">1 Shear Plane (Single Shear)</option>
              <option value="2">2 Shear Planes (Double Shear)</option>
            </select>
          </label>
          <label style={optLabel}>
            Limit State &nbsp;
            <select value={limitState} onChange={e => setLimitState(e.target.value)} style={optSel}>
              <option value="serviceability">Serviceability (φ = 1.00)</option>
              <option value="strength">Strength (φ = 0.85)</option>
            </select>
          </label>
        </div>
      )}

      {/* Table */}
      <div style={{ overflowX: 'auto' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 13 }}>
          <thead>
            <tr>
              <th style={th}>SIZE</th>
              {Object.keys(BOLT_SPECS).map(k => (
                <th key={k} style={{ ...th, color: BOLT_SPECS[k].common ? 'var(--val-warn)' : 'var(--tx-secondary)' }}>
                  {k}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {table.map(row => (
              <tr key={row.size}>
                <td style={{ ...td, fontWeight: 700, color: 'var(--tx-secondary)' }}>{row.size}</td>
                {Object.entries(row.values).map(([k, val]) => (
                  <td key={k} style={{
                    ...td, cursor: val !== '-' ? 'pointer' : 'default', textAlign: 'center',
                    color: BOLT_SPECS[k].common ? 'var(--val-warn)' : 'var(--val-pos)',
                    fontWeight: BOLT_SPECS[k].common ? 700 : 400,
                    background: cellHighlight(k, row.d_mm) ? 'var(--bg-active)' : 'transparent',
                  }}
                    onClick={() => val !== '-' && handleCellClick(k, row.d_mm)}
                  >
                    {val}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <p style={{ fontSize: 11, color: 'var(--tx-muted)', marginTop: 6 }}>Units: kN | Click a cell for detailed calculation</p>

      {/* Empty hint */}
      {!selected && (
        <div style={{ marginTop: 16, padding: '12px 16px', borderRadius: 8, background: 'var(--bg-inset)', border: '1px dashed var(--bd-subtle)', color: 'var(--tx-muted)', fontSize: 13 }}>
          ↑ Click a table cell to view the detailed calculation basis
        </div>
      )}

      {/* Detail panel */}
      {selected && detail && (
        <ResultBox title={`${selected.boltKey} M${selected.d_mm} — ${typeLabel} [${isSlip ? codeStd : 'AISC 360-16'}]`} accent>
          {isSlip ? (
            detail.code === 'KDS'
              ? <SlipDetailKDS d={detail} boltKey={selected.boltKey} d_mm={selected.d_mm} />
              : <SlipDetail    d={detail} boltKey={selected.boltKey} d_mm={selected.d_mm} />
          ) : (
            <BearingDetail
              d={detail} boltKey={selected.boltKey}
              d_mm={selected.d_mm} type={tab}
            />
          )}
        </ResultBox>
      )}
    </div>
  )
}

// ── Bearing / Tensile detail ──────────────────────────────────
function BearingDetail({ boltKey, d_mm, type }) {
  const spec = BOLT_SPECS[boltKey]
  const Ab   = Math.PI * d_mm * d_mm / 4
  const Fn   = type === 'shear-n' ? spec.Fnv_n
             : type === 'shear-x' ? spec.Fnv_x
             : spec.Fnt
  const fnLabel = type === 'tensile' ? 'Fnt' : 'Fnv'
  const phiRn = 0.75 * Fn * Ab / 1000

  return (
    <>
      <p style={valLine}>
        φRn = <Big>{phiRn.toFixed(2)} kN</Big>
      </p>
      <div style={formulaBox}>
        <div style={formulaTitle}>Calculation Basis — AISC 360-16 §J3.6</div>
        <FormulaLine label="Formula" expr="φRn = φ × Fn × Ab" />
        <hr style={hr} />
        <FormulaLine label="φ (LRFD)" expr="0.75" />
        <FormulaLine label={`${fnLabel} (${boltKey})`} expr={`${Fn} MPa`} />
        <FormulaLine label={`Ab (M${d_mm})`} expr={`π × ${d_mm}² / 4 = ${Ab.toFixed(1)} mm²`} />
        <hr style={hr} />
        <FormulaLine label="φRn" expr={`0.75 × ${Fn} × ${Ab.toFixed(1)} / 1000 = ${phiRn.toFixed(2)} kN`} highlight />
      </div>
      <p style={{ fontSize: 11, color: 'var(--tx-muted)', marginTop: 8 }}>
        {spec.name} | φ = 0.75 (LRFD)
      </p>
    </>
  )
}

// ── Slip-Critical detail ──────────────────────────────────────
function SlipDetail({ d, boltKey, d_mm }) {
  const { phiRn, phi, Tb, Du, hf, mu, ns } = d
  const slipClass = mu === 0.35 ? 'A' : 'B'

  return (
    <>
      <p style={valLine}>
        φRn = <Big>{phiRn.toFixed(2)} kN</Big>
      </p>
      <div style={formulaBox}>
        <div style={formulaTitle}>Calculation Basis — AISC 360-16 §J3.8</div>
        <FormulaLine label="Formula" expr="φRn = φ × μ × Du × hf × Tb × ns" />
        <hr style={hr} />
        <FormulaLine label="φ" expr={`${phi.toFixed(2)} (${phi === 1.00 ? 'Serviceability' : 'Strength'})`} />
        <FormulaLine label={`μ (Class ${slipClass})`} expr={`${mu.toFixed(2)}`} />
        <FormulaLine label="Du" expr={`${Du} (mean/specified pretension ratio)`} />
        <FormulaLine label="hf" expr={`${hf.toFixed(2)} (no filler plates)`} />
        <FormulaLine label={`Tb (M${d_mm}, ${boltKey})`} expr={`${Tb} kN`} />
        <FormulaLine label="ns" expr={`${ns} (${ns === 1 ? 'Single Shear' : 'Double Shear'})`} />
        <hr style={hr} />
        <FormulaLine
          label="φRn"
          expr={`${phi.toFixed(2)} × ${mu} × ${Du} × ${hf} × ${Tb} × ${ns} = ${phiRn.toFixed(2)} kN`}
          highlight
        />
      </div>
      <p style={{ fontSize: 11, color: 'var(--tx-muted)', marginTop: 8 }}>
        {BOLT_SPECS[boltKey].name} | Tb from AISC 360-16 Table J3.1
      </p>
    </>
  )
}

// ── KDS Slip-Critical detail ──────────────────────────────────
function SlipDetailKDS({ d, boltKey, d_mm }) {
  const { phiRn, phi, Tb, mu, ns } = d
  const slipClass = mu === 0.45 ? 'A' : 'B'
  const spec = BOLT_SPECS[boltKey]

  return (
    <>
      <p style={valLine}>φRs = <Big>{phiRn.toFixed(2)} kN</Big></p>
      <div style={formulaBox}>
        <div style={formulaTitle}>Calculation Basis — KDS 14 31 10 §4.4.1 미끄럼 설계저항력 (KS B 2819)</div>
        <FormulaLine label="Formula" expr="φRs = φ × μ × Tb × ns" />
        <hr style={hr} />
        <FormulaLine label="φ" expr={`${phi.toFixed(2)} (${phi === 1.00 ? 'Serviceability' : 'Strength'})`} />
        <FormulaLine label={`μ (Class ${slipClass})`} expr={`${mu.toFixed(2)}`} />
        <FormulaLine label={`Tb (M${d_mm}, ${boltKey})`} expr={`${Tb} kN  (KS B 2819 설계볼트장력)`} />
        <FormulaLine label="ns" expr={`${ns} (${ns === 1 ? 'Single Shear' : 'Double Shear'})`} />
        <hr style={hr} />
        <FormulaLine label="φRs" expr={`${phi.toFixed(2)} × ${mu} × ${Tb} × ${ns} = ${phiRn.toFixed(2)} kN`} highlight />
      </div>
      <p style={{ fontSize: 11, color: 'var(--tx-muted)', marginTop: 8 }}>
        {spec?.name} | Tb: KS B 2819 Table (설계볼트장력, Design Bolt Tension)
      </p>
    </>
  )
}

// ── Shared sub-components ─────────────────────────────────────
function FormulaLine({ label, expr, highlight }) {
  return (
    <div style={{ display: 'flex', justifyContent: 'space-between', padding: '3px 0', fontSize: 12, gap: 16 }}>
      <span style={{ color: 'var(--tx-secondary)', flexShrink: 0 }}>{label}</span>
      <span style={{
        fontWeight: highlight ? 700 : 500,
        color: highlight ? 'var(--val-pos)' : 'var(--tx-primary)',
        fontFamily: 'monospace', textAlign: 'right',
      }}>{expr}</span>
    </div>
  )
}

function Big({ children }) {
  return <span style={{ fontWeight: 700, color: 'var(--val-pos)', fontSize: 20 }}>{children}</span>
}

const titleStyle = { fontSize: '1.3rem', fontWeight: 700, marginBottom: 8, color: 'var(--tx-primary)', paddingBottom: 10, borderBottom: '1px solid var(--bd-subtle)' }
const descStyle  = { marginBottom: 20, color: 'var(--tx-secondary)', fontSize: 13 }
const th = { background: 'var(--bg-inset)', color: 'var(--ac-main)', fontWeight: 600, padding: '9px 12px', textAlign: 'left', borderBottom: '2px solid var(--bd-accent)', whiteSpace: 'nowrap' }
const td = { padding: '8px 12px', borderBottom: '1px solid var(--bd-subtle)' }
const optLabel = { display: 'flex', alignItems: 'center', gap: 4, color: 'var(--tx-secondary)', fontSize: 12, flexWrap: 'wrap' }
const optSel   = { background: 'var(--bg-input)', border: '1px solid var(--bd-subtle)', borderRadius: 5, color: 'var(--tx-primary)', padding: '4px 6px', fontSize: 12 }
const valLine  = { fontSize: 15, color: 'var(--tx-primary)', marginBottom: 12 }
const formulaBox = {
  background: 'var(--bg-inset)', borderRadius: 6,
  padding: '10px 14px', marginTop: 4,
  border: '1px solid var(--bd-subtle)',
}
const formulaTitle = { fontSize: 11, fontWeight: 700, color: 'var(--ac-main)', marginBottom: 8, letterSpacing: '0.05em' }
const hr = { border: 'none', borderTop: '1px solid var(--bd-subtle)', margin: '6px 0' }
