/**
 * Bolt 설계 강도
 * AISC 360-16 §J3.6 Bearing/Tensile LRFD (φ = 0.75)
 * AISC 360-16 §J3.8 Slip-Critical LRFD
 * 볼트 규격: KS B 1010 (F8T/F10T/F13T) + ASTM (A325M/A490M)
 */

export const BOLT_SPECS = {
  F8T:   { name: 'KS B 1010 F8T',  Fnt: 630, Fnv_n: 372, Fnv_x: 457, common: false },
  A325M: { name: 'A325M (F1852TC)', Fnt: 620, Fnv_n: 372, Fnv_x: 457, common: true  },
  F10T:  { name: 'KS B 1010 F10T', Fnt: 750, Fnv_n: 450, Fnv_x: 563, common: true  },
  A490M: { name: 'A490M (F2280TC)', Fnt: 825, Fnv_n: 495, Fnv_x: 620, common: false },
  F13T:  { name: 'KS B 1010 F13T', Fnt: 975, Fnv_n: 585, Fnv_x: 731, common: false },
};

export const BOLT_SIZES = [16, 20, 22, 24, 27, 30]; // mm

// ── Slip-Critical 최소 체결력 Tb (kN) — AISC 360-16 Table J3.1
// KS F8T / F10T: KS B 2819 기준 (≈ 0.7 × Fnp × Ab)
const TB_TABLE = {
  // [d_mm]: { A325M, A490M, F8T, F10T, F13T }
  16: { A325M:  91, A490M: 113, F8T:  80, F10T: 101, F13T: 131 },
  20: { A325M: 142, A490M: 179, F8T: 124, F10T: 157, F13T: 204 },
  22: { A325M: 176, A490M: 221, F8T: 151, F10T: 191, F13T: 248 },
  24: { A325M: 205, A490M: 257, F8T: 179, F10T: 226, F13T: 294 },
  27: { A325M: 267, A490M: 334, F8T: 234, F10T: 296, F13T: 384 },
  30: { A325M: 326, A490M: 408, F8T: 285, F10T: 360, F13T: 468 },
};

/**
 * @param {'tensile'|'shear-n'|'shear-x'} type
 * @param {string} boltKey
 * @param {number} d_mm
 * @returns {number} φRn (kN)
 */
export function calcBoltStrength(type, boltKey, d_mm) {
  const spec = BOLT_SPECS[boltKey];
  if (!spec) return 0;
  const Ab = Math.PI * d_mm * d_mm / 4;
  const Fn = type === 'shear-n' ? spec.Fnv_n
           : type === 'shear-x' ? spec.Fnv_x
           : spec.Fnt;
  return 0.75 * Fn * Ab / 1000;
}

/**
 * Slip-Critical — AISC 360-16 §J3.8
 * φRn = φ × μ × Du × hf × Tb × ns
 */
export function calcSlipCriticalAISC(boltKey, d_mm, mu, ns, limitState) {
  const Tb = TB_TABLE[d_mm]?.[boltKey];
  if (!Tb) return null;
  const phi = limitState === 'strength' ? 0.85 : 1.00;
  const Du  = 1.13;
  const hf  = 1.00;
  const phiRn = phi * mu * Du * hf * Tb * ns;
  return { phiRn, phi, Tb, Du, hf, mu, ns, code: 'AISC', codeRef: 'AISC 360-16 §J3.8' };
}

/**
 * Slip-Critical — KDS 14 31 10 §4.4.1 (KS B 2819)
 * φRs = φ × μ × Tb × ns
 * Tb = 설계볼트장력 (design bolt tension) from TB_TABLE (KS B 2819)
 * KDS surface class: A = 0.45 (unpainted), B = 0.50 (blast-cleaned)
 */
export function calcSlipCriticalKDS(boltKey, d_mm, mu_kds, ns, limitState) {
  const Tb = TB_TABLE[d_mm]?.[boltKey];
  if (!Tb) return null;
  const phi = limitState === 'strength' ? 0.85 : 1.00;
  const phiRn = phi * mu_kds * Tb * ns;
  return { phiRn, phi, Tb, mu: mu_kds, ns, code: 'KDS', codeRef: 'KDS 14 31 10 §4.4' };
}

// Keep old alias for compat
export function calcSlipCritical(boltKey, d_mm, mu, ns, limitState) {
  return calcSlipCriticalAISC(boltKey, d_mm, mu, ns, limitState);
}

export function buildBoltTable(type) {
  return BOLT_SIZES.map(d => ({
    size: `M${d}`,
    d_mm: d,
    values: Object.fromEntries(
      Object.keys(BOLT_SPECS).map(k => [k, Math.round(calcBoltStrength(type, k, d))])
    ),
  }));
}

export function buildSlipTable(mu, ns, limitState, code = 'AISC') {
  return BOLT_SIZES.map(d => ({
    size: `M${d}`,
    d_mm: d,
    values: Object.fromEntries(
      Object.keys(BOLT_SPECS).map(k => {
        const r = code === 'KDS'
          ? calcSlipCriticalKDS(k, d, mu, ns, limitState)
          : calcSlipCriticalAISC(k, d, mu, ns, limitState);
        return [k, r ? Math.round(r.phiRn) : '-'];
      })
    ),
  }));
}
